using System;using System.Linq;using System.Reflection;using Assets.Script.Constants;using Assets.Script.Models;using UnityEditor.SceneManagement;using UnityEngine;using UnityEngine.UI;
public static class PracticeValidation {
 static readonly BindingFlags Flags=BindingFlags.Instance|BindingFlags.NonPublic|BindingFlags.Public;
 static void Set(object o,string name,object value){o.GetType().GetField(name,Flags).SetValue(o,value);}
 static object Get(object o,string name){return o.GetType().GetField(name,Flags).GetValue(o);}
 static void Check(bool okay,string message){if(!okay)throw new Exception(message);}
 public static void Review(){
  const int owner=1999999923;var prior=UserConstants.s_user;bool challenge=ChallengeConstants.s_isChallenge;UserConstants.s_user=new User{id=owner,username="Practice review"};ChallengeConstants.s_isChallenge=false;EditorSceneManager.NewScene(NewSceneSetup.EmptyScene);var root=new GameObject("Practice review",typeof(RectTransform),typeof(Canvas));var rect=(RectTransform)root.transform;rect.sizeDelta=new Vector2(800,1734);
  try{
   MemorySettings.Practice=true;Check(PracticeMode.Untimed,"Saved training preference");ChallengeConstants.s_isChallenge=true;Check(!PracticeMode.Untimed,"Legacy challenges ignore Practice");ChallengeConstants.s_isChallenge=false;
   for(int kind=0;kind<4;kind++){var game=FocusGame.Open(rect,kind);game.Begin();game.Tick(1000);Check((bool)Get(game,"playing")&&((Text)Get(game,"clock")).text=="∞","Untimed Focus "+kind);if(kind==0){var sum=(FocusRules.Sum)Get(game,"sum");foreach(char digit in sum.Answer.ToString())game.MathKey(digit.ToString());game.MathKey("OK");Check((int)Get(game,"score")==1,"Math still works after original deadline");}typeof(FocusGame).GetMethod("Primary",Flags).Invoke(game,null);Check(!(bool)Get(game,"playing"),"Finish closes practice run");game.Close();}
   Check(FocusStats.Read(owner).games.Sum(g=>g.sessions)==0,"Practice must not create90second records");
   foreach(Type type in new[]{typeof(PairsManager),typeof(BoxesManager),typeof(FlashManager)}){var go=new GameObject("Legacy practice");var manager=go.AddComponent(type);Set(manager,"shouldCountTime",true);Set(manager,"countdownTime",-10f);var label=ChainGame.Label(root.transform,"",Vector2.zero,Vector2.one,30,Color.black);if(type==typeof(PairsManager)){Set(manager,"firstCountDown",label);Set(manager,"firstCountDownIpad",label);Set(manager,"secondCountDown",label);}else Set(manager,type==typeof(BoxesManager)?"countDownText":"timerText",label);type.GetMethod("Update",Flags).Invoke(manager,null);Check(label.text=="∞","Legacy timer must stay untimed: "+type.Name);UnityEngine.Object.DestroyImmediate(go);}
   CardFaces.Selected=CardFaces.Choice.Images;var chain=root.AddComponent<ChainGame>();chain.Open();chain.StartLevel(1);for(int n=0;n<3;n++)chain.NextCard();typeof(ChainGame).GetMethod("TickTrainingClock",Flags).Invoke(chain,new object[]{1000f});Check(!((ChainState)Get(chain,"state")).Finished,"Chain cannot time out in Practice");typeof(ChainGame).GetMethod("Close",Flags).Invoke(chain,null);
   var says=SaysGame.Open(rect);says.StartLevel(1);says.BeginPlayback();says.Tick(10);says.Tick(1000);Check((bool)Get(says,"input"),"Says recall remains playable without time");says.Close();
   MemorySettings.Practice=false;var timed=FocusGame.Open(rect,0);timed.Begin();timed.Tick(91);Check(!(bool)Get(timed,"playing"),"Normal Focus retains90second end");timed.Close();Debug.Log("PRACTICE_VALIDATION_PASSED: setting and legacy challenge override, four untimed Focus games, math after deadline, Finish, no timed records, three legacy timers, Chain/Says recall and normal90second Focus");
  }finally{foreach(string key in new[]{"memory.settings.v1."+owner+".practice","focus.stats.device.v1."+owner,"achievements.verified.v2."+owner,"achievements.pending.v2."+owner})PlayerPrefs.DeleteKey(key);UserConstants.s_user=prior;ChallengeConstants.s_isChallenge=challenge;CardFaces.EndSession();UnityEngine.Object.DestroyImmediate(root);}
 }
}
